package ngl.relay.app;
import android.app.*;import android.os.*;import android.content.*;import android.widget.*;
public final class MainActivity extends Activity { public void onCreate(Bundle b){super.onCreate(b);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(24,24,24,24);TextView title=new TextView(this);title.setText("NGL Relay");title.setTextSize(28);root.addView(title);EditText input=new EditText(this);input.setHint("Paste or type the question / material to analyze");input.setMinLines(4);root.addView(input);Button start=new Button(this);start.setText("START NEW CASE");root.addView(start);Button settings=new Button(this);settings.setText("SETTINGS — COGNITION NODES");settings.setOnClickListener(v->startActivity(new Intent(this,SettingsActivity.class)));root.addView(settings);TextView note=new TextView(this);note.setText("Persistent case records across cognition nodes. Local-first. Nothing is deleted.");root.addView(note);setContentView(root);} }
